static void drawInitWordmark(int left,int top,int width,uint16_t color) {
  if(width<1 || width>468)return;
  const int height=max(1,(width*115+256)/512);
  for(int y=0;y<height;y++) {
    const int sy=(2*y+1)*115/(2*height);int start=-1;
    for(int x=0;x<=width;x++) {
      bool ink=false;
      if(x<width) {
        int sx=(2*x+1)*512/(2*width);
        ink=(pgm_read_byte(INIT_WORDMARK_BITS+sy*64+sx/8) & (0x80>>(sx%8)))!=0;
      }
      if(ink && start<0)start=x;
      if(!ink && start>=0) {M5.Display.drawFastHLine(left+start,top+y,x-start,color);start=-1;}
    }
  }
}
